CREATE TABLE orders(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,total_minor INTEGER NOT NULL,requested INTEGER NOT NULL DEFAULT 0,
 state TEXT NOT NULL DEFAULT 'open',cash_minor INTEGER,return_state TEXT NOT NULL DEFAULT 'none');
CREATE TABLE lots(id INTEGER PRIMARY KEY,order_id TEXT UNIQUE NOT NULL REFERENCES orders(id),user_id INTEGER NOT NULL,
 points INTEGER NOT NULL,remaining INTEGER NOT NULL,expired INTEGER NOT NULL DEFAULT 0,expires_at INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE allocations(order_id TEXT NOT NULL REFERENCES orders(id),lot_id INTEGER NOT NULL REFERENCES lots(id),points INTEGER NOT NULL,PRIMARY KEY(order_id,lot_id));
CREATE TABLE ledger(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,event_key TEXT UNIQUE NOT NULL,kind TEXT NOT NULL,delta INTEGER NOT NULL,created_at INTEGER NOT NULL);
